const opType = msg.operationType || 'read';

if (opType === 'write') {
    return [null, msg];
} else {
    return [msg, null];
}

// Clear previous collected data first
flow.set('gc_reads', null);

// Save RPC response topic for later
flow.set('gc_rpc_response_topic', msg.rpcResponseTopic);
flow.set('gc_write_result', msg.writeResult || null);

// Read all registers in parallel
const reads = [
    { name: 'gridModeRaw', address: 282, quantity: 1 },
    { name: 'gridFrequencyHz', address: 283, quantity: 1 },
    { name: 'outputVoltageLevelCode', address: 238, quantity: 1 },
    { name: 'normalConnect', address: 285, quantity: 4 },  // 285-288
    { name: 'reconnectionTimeSeconds', address: 280, quantity: 1 },
    { name: 'powerFactorTarget', address: 293, quantity: 1 },
    { name: 'activePowerReg', address: 177, quantity: 1 },
    { name: 'reactivePowerReg', address: 178, quantity: 1 }
];

const messages = reads.map(r => ({
    payload: {
        fc: 3,
        unitid: 1,
        address: r.address,
        quantity: r.quantity
    },
    readName: r.name
}));

return [messages];

const flowKey = 'gc_reads';
let collected = flow.get(flowKey) || {};
let expectedCount = 8;

let data = msg.payload;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

if (!Array.isArray(data) || data.length < 1) {
    node.status({ fill: "red", shape: "dot", text: "Read failed: " + msg.readName });
    return null;
}

const readName = msg.readName;

if (readName === 'normalConnect') {
    collected[readName] = {
        voltageHighV: data[0],
        voltageLowV: data[1],
        frequencyHighHz: data[2],
        frequencyLowHz: data[3]
    };
} else {
    collected[readName] = data[0];
}

flow.set(flowKey, collected);

const collectedCount = Object.keys(collected).length;
node.status({ fill: "blue", shape: "dot", text: `Collected ${collectedCount}/${expectedCount}` });

if (collectedCount >= expectedCount) {
    flow.set(flowKey, null);
    msg.collectedData = collected;
    msg.payload = collected;
    return msg;
}

return null;

const data = msg.collectedData;

if (!data) {
    node.status({ fill: 'red', shape: 'dot', text: 'No data' });
    return null;
}

const gatewayId = global.get('GATEWAY_ID') || env.get('GATEWAY_ID') || 'EC100-GW-001';

// Apply scaling factors
const normalConnect = data.normalConnect || {};

const state = {
    kind: 'GridCodeConfigState',
    timestampUtc: new Date().toISOString(),
    version: 1,
    gatewayId: gatewayId,
    gridModeRaw: data.gridModeRaw,
    gridFrequencyHz: data.gridFrequencyHz === 0 ? 50 : 60,
    outputVoltageLevelCode: data.outputVoltageLevelCode,
    normalConnect: {
        voltageHighV: normalConnect.voltageHighV / 10,
        voltageLowV: normalConnect.voltageLowV / 10,
        frequencyHighHz: normalConnect.frequencyHighHz / 100,
        frequencyLowHz: normalConnect.frequencyLowHz / 100
    },
    reconnectionTimeSeconds: data.reconnectionTimeSeconds,
    powerFactorTarget: data.powerFactorTarget / 10,
    activePowerRegulationPercentPerStep: data.activePowerReg === 65535 ? null : data.activePowerReg,
    reactivePowerRegulationPercentPerStep: data.reactivePowerReg === 65535 ? null : data.reactivePowerReg
};

// Get write result and rpc topic from flow context
const writeResult = flow.get('gc_write_result');
const rpcResponseTopic = flow.get('gc_rpc_response_topic');

// Clear flow context
flow.set('gc_write_result', null);
flow.set('gc_rpc_response_topic', null);

// Build response
if (writeResult) {
    msg.payload = {
        success: writeResult.success,
        message: writeResult.message,
        writes: writeResult.writes,
        state: state
    };
} else {
    msg.payload = state;
}

msg.state = state;
msg.rpcResponseTopic = rpcResponseTopic;

node.status({ fill: 'green', shape: 'dot', text: `Mode: ${state.gridModeRaw}, ${state.gridFrequencyHz}Hz` });

return msg;

const params = msg.rpcParams || {};
const writes = [];

// 282: gridModeRaw
if (params.gridModeRaw !== undefined) {
    writes.push({ name: 'gridModeRaw', address: 282, value: [params.gridModeRaw] });
}

// 283: gridFrequencyHz
if (params.gridFrequencyHz !== undefined) {
    const val = params.gridFrequencyHz === 50 ? 0 : 1;
    writes.push({ name: 'gridFrequencyHz', address: 283, value: [val] });
}

// 238: outputVoltageLevelCode
if (params.outputVoltageLevelCode !== undefined) {
    writes.push({ name: 'outputVoltageLevelCode', address: 238, value: [params.outputVoltageLevelCode] });
}

// normalConnect - each register separately
if (params.normalConnect) {
    const nc = params.normalConnect;

    // 285: voltageHighV (0.1V scale)
    if (nc.voltageHighV !== undefined) {
        writes.push({ name: 'voltageHighV', address: 285, value: [Math.round(nc.voltageHighV * 10)] });
    }

    // 286: voltageLowV (0.1V scale)
    if (nc.voltageLowV !== undefined) {
        writes.push({ name: 'voltageLowV', address: 286, value: [Math.round(nc.voltageLowV * 10)] });
    }

    // 287: frequencyHighHz (0.01Hz scale)
    if (nc.frequencyHighHz !== undefined) {
        writes.push({ name: 'frequencyHighHz', address: 287, value: [Math.round(nc.frequencyHighHz * 100)] });
    }

    // 288: frequencyLowHz (0.01Hz scale)
    if (nc.frequencyLowHz !== undefined) {
        writes.push({ name: 'frequencyLowHz', address: 288, value: [Math.round(nc.frequencyLowHz * 100)] });
    }
}

// 280: reconnectionTimeSeconds
if (params.reconnectionTimeSeconds !== undefined) {
    writes.push({ name: 'reconnectionTimeSeconds', address: 280, value: [params.reconnectionTimeSeconds] });
}

// 293: powerFactorTarget
if (params.powerFactorTarget !== undefined) {
    const val = Math.round(params.powerFactorTarget * 10);
    writes.push({ name: 'powerFactorTarget', address: 293, value: [val] });
}

// 177: activePowerRegulationPercentPerStep
if (params.activePowerRegulationPercentPerStep !== undefined) {
    writes.push({ name: 'activePowerReg', address: 177, value: [params.activePowerRegulationPercentPerStep] });
}

// 178: reactivePowerRegulationPercentPerStep
if (params.reactivePowerRegulationPercentPerStep !== undefined) {
    writes.push({ name: 'reactivePowerReg', address: 178, value: [params.reactivePowerRegulationPercentPerStep] });
}

if (writes.length === 0) {
    node.status({ fill: 'red', shape: 'dot', text: 'No valid params' });
    node.error('No valid parameters to write');
    return null;
}

// Store write queue in global context
global.set('gc_write_queue', writes);
global.set('gc_write_index', 0);
global.set('gc_write_results', []);

// Store original message for later
flow.set('gc_original_msg', msg);

node.status({ fill: 'yellow', shape: 'dot', text: `Queued ${writes.length} writes` });

return msg;

const queue = global.get('gc_write_queue') || [];
let index = global.get('gc_write_index') || 0;
const results = global.get('gc_write_results') || [];

if (index >= queue.length) {
    node.status({ fill: 'green', shape: 'dot', text: 'All writes complete' });

    // Get original message info
    const originalMsg = flow.get('gc_original_msg');
    const rpcTopic = originalMsg ? originalMsg.rpcResponseTopic : null;

    // Clear global context
    global.set('gc_write_queue', null);
    global.set('gc_write_index', null);
    global.set('gc_write_results', null);
    flow.set('gc_original_msg', null);

    // Build write result
    const writeResult = {
        success: true,
        message: `Successfully wrote ${results.length} register(s)`,
        writes: results
    };

    // Trigger auto-read after all writes
    const readMsg = {
        operationType: 'read',
        rpcResponseTopic: rpcTopic,
        writeResult: writeResult
    };

    setTimeout(() => {
        node.send([null, readMsg]);
    }, 500);

    return null;
}

const write = queue[index];

msg.payload = {
    fc: 16,
    unitid: 1,
    address: write.address,
    quantity: write.value.length,
    value: write.value
};

msg.writeInfo = write;
msg.writeIndex = index;

node.status({ fill: 'yellow', shape: 'dot', text: `Writing ${write.name} (${index + 1}/${queue.length})` });

// Increment index for next write
global.set('gc_write_index', index + 1);

// Record this write for results
results.push({ register: write.address, name: write.name, value: write.value, success: true });
global.set('gc_write_results', results);

return [msg, null];

// Check if this is actually an error or just a success confirmation
// Success confirmation has 'address' and 'length' properties
// Real errors have 'error' property or different structure
const p = msg.payload;

if (!p || Object.keys(p).length === 0) {
    // Empty message - ignore
    return null;
}

// If it has address and length, it's a success confirmation - ignore
if (p.address !== undefined && p.length !== undefined && !p.error) {
    return null;
}

// Real error - log it
node.warn('Write error: ' + JSON.stringify(p));
node.status({ fill: 'red', shape: 'dot', text: 'Write error' });
return null;

// Success - continue to next write after delay
const writeInfo = msg.writeInfo || {};
node.status({ fill: 'green', shape: 'dot', text: writeInfo.name + ' OK' });

setTimeout(() => {
    node.send(msg);
}, 500);

return null;

if (!msg.rpcResponseTopic) {
    return null;
}

msg.topic = msg.rpcResponseTopic;
return msg;
